import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.DncwoWA8.js";const o="/projects/ai-skills/diagrams/shape-an-initiative.svg",m=JSON.parse('{"title":"Turn an idea into an outcome-level brief","description":"","frontmatter":{"title":"Turn an idea into an outcome-level brief"},"headers":[],"relativePath":"workflows/shape-an-initiative.md","filePath":"workflows/shape-an-initiative.md"}'),r={name:"workflows/shape-an-initiative.md"};function n(l,e,h,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="turn-an-idea-into-an-outcome-level-brief" tabindex="-1">Turn an idea into an outcome-level brief <a class="header-anchor" href="#turn-an-idea-into-an-outcome-level-brief" aria-label="Permalink to &quot;Turn an idea into an outcome-level brief&quot;">​</a></h1><p>The problem and success measures are less clear than the proposed solution.</p><p><strong>Finish with:</strong> An agreed problem, outcomes, scope, constraints, and success measures.</p><h2 id="read-the-diagram" tabindex="-1">Read the diagram <a class="header-anchor" href="#read-the-diagram" aria-label="Permalink to &quot;Read the diagram&quot;">​</a></h2><p><img src="'+o+'" alt="Turn an idea into an outcome-level brief: suggested skill handoffs with approval stops where applicable."></p><p><a href="/projects/ai-skills/diagrams/shape-an-initiative.html">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/shape-an-initiative.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/shape-an-initiative.json">Editable candidate</a></p><p>Arrows show this suggested sequence, not declared <code>requires</code> dependencies. Approval arrows are conditional. Declining a gate stops that branch without authorizing its writes. The numbered steps below are the text equivalent of the diagram.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Use a trusted project and follow its instructions. Confirm the requested scope, installed skills, runtime tools, and any required workspace or approval. This selection includes the catalogued instruction requirements <a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a>. Resolve them before use.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Describe the problem.</strong> <a href="/projects/ai-skills/skills/initiative.html"><code>initiative</code></a> provides the guidance for this step.</li><li><strong>Interview about outcomes.</strong> <a href="/projects/ai-skills/skills/grilling.html"><code>grilling</code></a> provides the guidance for this step.</li><li><strong>Bound scope and measures.</strong> <a href="/projects/ai-skills/skills/initiative.html"><code>initiative</code></a> provides the guidance for this step.</li><li><strong>Record the agreed brief.</strong> <a href="/projects/ai-skills/skills/initiative.html"><code>initiative</code></a> provides the guidance for this step.</li></ol><h2 id="where-to-stop" tabindex="-1">Where to stop <a class="header-anchor" href="#where-to-stop" aria-label="Permalink to &quot;Where to stop&quot;">​</a></h2><p>Use research only if facts are missing. A completed brief does not automatically start specification or implementation.</p><h2 id="optional-branches" tabindex="-1">Optional branches <a class="header-anchor" href="#optional-branches" aria-label="Permalink to &quot;Optional branches&quot;">​</a></h2><ul><li>Choose <a href="/projects/ai-skills/skills/research.html"><code>research</code></a> when a decision depends on facts, alternatives, feasibility, or evidence that you do not yet have.</li><li>Choose <a href="/projects/ai-skills/skills/wait-what.html"><code>wait-what</code></a> when the last answer is hard to understand or omits context needed to follow the current proposal.</li></ul><p>Optional branches are not prerequisites or permission to launch another phase. You can omit them or stop at the stated result. See <a href="/projects/ai-skills/reference/relationships.html">relationship types</a> for the distinction.</p>',16)])])}const f=a(r,[["render",n]]);export{m as __pageData,f as default};
